<?php
declare(strict_types=1);
require __DIR__.'/../server/Leaderboard.php';
use StarRebound\Leaderboard; use StarRebound\ApiError;
$results=[];$clock=1000.0;
function check($ok,$msg){if(!$ok)throw new RuntimeException($msg);}
function test($name,$fn){global $results;try{$fn();$results[]=['name'=>$name,'status'=>'PASS'];}catch(Throwable $e){$results[]=['name'=>$name,'status'=>'FAIL','message'=>$e->getMessage()];}}
function setup(){ $db=new PDO('sqlite::memory:');return [$db,new Leaderboard($db,fn()=>$GLOBALS['clock'])]; }
function payload($store,$actor='fixture',$points=120,$details=true){$r=$store->start($actor,'nightmare');$GLOBALS['clock']+=10;$p=['runId'=>$r['runId'],'nonce'=>$r['nonce'],'difficulty'=>$r['difficulty'],'ruleset'=>$r['ruleset'],'seed'=>$r['seed'],'name'=>'合成星','score'=>$points,'time'=>8.0,'result'=>'lost','stageIndex'=>0,'completedStages'=>0,'hp'=>0,'kills'=>$points?1:0,'returned'=>0,'bestCombo'=>$points?1:0,'hits'=>2,'captureUses'=>0];if($details)$p['details']=['version'=>1,'heals'=>0,'scoreBreakdown'=>['defeats'=>$points,'returns'=>0,'lifeBonus'=>0]];return $p;}
test('new records expose stats and exact details tied to best; equal and lower preserve them',function(){[$db,$s]=setup();check($s->start('cap','nightmare')['detailsVersion']===1,'capability missing');$p=payload($s);$a=$s->finish('fixture',$p);check($a===$s->finish('fixture',$p),'retry changed');$d=$a['entry']['details'];check($d['time']===8.0&&$d['kills']===1&&$d['heals']===0&&$d['scoreBreakdown']['defeats']===120,'details missing');foreach([120,0]as $score){$q=payload($s,'fixture',$score);$q['time']=9.0;$b=$s->finish('fixture',$q);check(!$b['improved']&&$b['entry']['details']===$d,'best replaced');}check($s->top('nightmare')['entries'][0]['details']===$d,'top differs');});
test('legacy payload accepts base stats and old rows remain unrecorded',function(){[$db,$s]=setup();$p=payload($s,'old-client',120,false);$a=$s->finish('old-client',$p);check($a['entry']['details']['kills']===1&&$a['entry']['details']['heals']===null&&$a['entry']['details']['scoreBreakdown']===null,'base stats not preserved');$q=$db->prepare('INSERT INTO scores(browser,difficulty,ruleset,name,score,stage,cleared,recorded) VALUES(?,?,?,?,?,?,?,?)');$q->execute(['old-row','nightmare',Leaderboard::RULESET,'旧星',240,0,0,1]);check($s->top('nightmare')['entries'][0]['details']===null,'legacy invented stats');check((int)$db->query('PRAGMA user_version')->fetchColumn()===1,'base version changed');});
test('invalid detail sums, types and return/life constraints reject atomically',function(){foreach(['sum','return','bonus','float','extra','heal']as $case){[$db,$s]=setup();$p=payload($s);if($case==='sum')$p['details']['scoreBreakdown']['defeats']=124;if($case==='return')$p['details']['scoreBreakdown']=['defeats'=>108,'returns'=>12,'lifeBonus'=>0];if($case==='bonus')$p['details']['scoreBreakdown']=['defeats'=>0,'returns'=>0,'lifeBonus'=>120];if($case==='float')$p['details']['scoreBreakdown']['defeats']=120.0;if($case==='extra')$p['details']['secret']='x';if($case==='heal')$p['details']['heals']=4;try{$s->finish('fixture',$p);throw new RuntimeException('invalid accepted: '.$case);}catch(ApiError $e){check($e->status===422,'wrong rejection');}check((int)$db->query('SELECT COUNT(*) FROM scores')->fetchColumn()===0,'invalid saved');}});
test('metadata failure rolls back score and run then exact retry succeeds',function(){[$db,$s]=setup();$p=payload($s);$db->exec("CREATE TRIGGER fail_details BEFORE INSERT ON score_details BEGIN SELECT RAISE(ABORT,'synthetic failure'); END");try{$s->finish('fixture',$p);throw new RuntimeException('failure not injected');}catch(PDOException $e){}check((int)$db->query('SELECT COUNT(*) FROM scores')->fetchColumn()===0,'score escaped transaction');check((int)$db->query('SELECT COUNT(*) FROM runs WHERE response IS NOT NULL')->fetchColumn()===0,'run escaped transaction');$db->exec('DROP TRIGGER fail_details');check($s->finish('fixture',$p)['accepted'],'retry failed');});
test('legacy server write invalidates stale details without schema changes',function(){[$db,$s]=setup();$s->finish('fixture',payload($s));$db->exec('UPDATE scores SET score=240,recorded=recorded+1');check($s->top('nightmare')['entries'][0]['details']===null,'stale details exposed');});
test('legacy canonical hash and persisted retry response remain unchanged',function(){[$db,$s]=setup();$p=payload($s,'legacy-hash',120,false);$expected=hash('sha256',json_encode($p,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));$oldResponse=['accepted'=>true,'improved'=>true,'entry'=>['rank'=>1,'name'=>'合成星','score'=>120,'stage'=>1,'clear'=>false],'ruleset'=>Leaderboard::RULESET];$q=$db->prepare('UPDATE runs SET payload_hash=?,response=?,completed=? WHERE id=?');$q->execute([$expected,json_encode($oldResponse,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$GLOBALS['clock'],$p['runId']]);check($s->finish('legacy-hash',$p)===$oldResponse,'legacy retry changed');});
test('three-stage exact life bonus accepts and preserves the upper bound',function(){[$db,$s]=setup();$p=payload($s,'clear');$GLOBALS['clock']+=300;$p=array_replace($p,['score'=>12000,'time'=>280.0,'result'=>'stage-clear','stageIndex'=>2,'completedStages'=>3,'hp'=>2,'kills'=>3,'bestCombo'=>3,'hits'=>0,'captureUses'=>0,'details'=>['version'=>1,'heals'=>0,'scoreBreakdown'=>['defeats'=>9000,'returns'=>0,'lifeBonus'=>3000]]]);check($s->finish('clear',$p)['entry']['details']['scoreBreakdown']['lifeBonus']===3000,'clear rejected');});
$failed=count(array_filter($results,fn($r)=>$r['status']==='FAIL'));echo json_encode(['failed'=>$failed,'results'=>$results],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);exit($failed?1:0);
